def compute(vars):
    current_liabilities = vars["v1"]
    other_non_current_liabilities = vars["v2"]
    total_liabilities = current_liabilities + other_non_current_liabilities

    return {
        "value": total_liabilities,
        "trace": {
            "current_liabilities": current_liabilities,
            "other_non_current_liabilities": other_non_current_liabilities,
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": None
            }
        }
    }
